const assert=require('assert/strict'),fs=require('fs'),path=require('path'),vm=require('vm');
const P=require('../../dist/customer-profiles.js'),A=require('../../dist/invoice-customer-links.js');
const root=path.resolve(__dirname,'../..'),html=fs.readFileSync(path.join(root,'dist/index.html'),'utf8');
let count=0;function test(name,fn){fn();console.log('PASS '+name);count++;}
function generic(a,b){return Object.assign({},a,b);}
function customers(){return [{id:'nasir',name:'Nasir Bagali',mobile:'',vat:'NASIR-VAT',address:'Nasir address',nationalAddress:'NASIR-NATIONAL'},{id:'company',name:'Nabd Al Gharb',mobile:'0501234567',vat:'COMPANY-VAT',address:'Company address',nationalAddress:'COMPANY-NATIONAL'}];}
function decoded(key){return Buffer.from(html.match(new RegExp('\\b'+key+'=b64utf8\\("([^\"]+)"\\)'))[1],'base64').toString('utf8');}
test('Switching from Nabd Al Gharb to Nasir replaces every customer field, including blank mobile',()=>{const c=customers(),state={key:null};let fields=P.fill(state,c[1].name,c[1],{});fields=P.fill(state,c[0].name,c[0],fields);assert.equal(fields.vat,'NASIR-VAT');assert.equal(fields.address,'Nasir address');assert.equal(fields.mobile,'');assert.equal(fields.nationalAddress,'NASIR-NATIONAL');});
test('Switching to a new unknown customer clears the previous VAT, address and mobile',()=>{const state={key:'nabd al gharb'},fields=P.fill(state,'New Customer',null,{vat:'COMPANY-VAT',address:'Company address',mobile:'0501234567'});assert.equal(fields.vat,'');assert.equal(fields.address,'');assert.equal(fields.mobile,'');});
test('Typing again within the same customer preserves manual invoice detail edits',()=>{const state={key:'nasir bagali'},fields=P.fill(state,'Nasir Bagali',customers()[0],{vat:'ONE-OFF',address:'One-off address'});assert.equal(fields.vat,'ONE-OFF');});
test('Explicit empty VAT and address remain empty after merging older cloud values',()=>{const old=customers()[0],saved={...old,vat:'',address:'',nationalAddress:'',updated_at:'2026-11-01T10:00:00Z'};P.stamp(saved,old.name,'2026-11-01T10:00:00Z');const merged=P.merge(saved,{...old,updated_at:'2026-12-01T10:00:00Z'},generic);assert.equal(merged.vat,'');assert.equal(merged.vatNumber,'');assert.equal(merged.address,'');assert.equal(merged.national_address,'');});
test('The latest explicit customer profile wins as a complete set of details',()=>{const a=customers()[0],b={...a,vat:'NEW',address:'New address'};P.stamp(a,a.name,'2026-10-01');P.stamp(b,b.name,'2026-11-01');const merged=P.merge(a,b,generic);assert.equal(merged.vat,'NEW');assert.equal(merged.address,'New address');});
test('Matching does not treat a reused ID as proof that different customer names are the same',()=>{const a=customers()[0],b={...customers()[1],id:a.id};assert.equal(P.match([a],b),null);assert.notEqual(P.uniqueId([a],b),a.id);assert.throws(()=>P.merge(a,b,generic),/different customers/);});
test('A deliberate customer rename records its previous name and still syncs by ID',()=>{const old=customers()[0],renamed={...old,name:'Nasir Bagali New'};P.stamp(renamed,old.name);assert.equal(P.match([old],renamed),old);assert.equal(P.merge(old,renamed,generic).name,'Nasir Bagali New');});
test('Duplicate names are not resolved by picking an arbitrary customer',()=>{const a=customers()[0];assert.equal(P.find([a,{...a,id:'other'}],a.name),null);});
test('An incompatible copied profile snapshot cannot change another customer name or details',()=>{const a=customers()[0],b=customers()[1];P.stamp(b);a.profile_v226=b.profile_v226;P.apply(a);assert.equal(a.name,'Nasir Bagali');assert.equal(a.vat,'NASIR-VAT');});
function formHarness(key){
  let d={customers:customers(),entries:{},settings:{}},writes=0;const ctx={window:{parent:{NagCustomerProfiles:P}},loadLedgerData:()=>structuredClone(d),persistLedgerData:x=>{d=x;writes++;},nagBridgeMark:x=>x};vm.createContext(ctx);
  const doc=decoded(key),start=doc.indexOf('  function findLedgerCustomerByName('),end=doc.indexOf('  function ledgerCustomerOutstanding(',start);vm.runInContext(doc.slice(start,end),ctx);return {ctx,get data(){return d;},get writes(){return writes;}};
}
for(const key of ['INV','RECV'])test(key+' does not copy incoming document details into an existing customer profile',()=>{const h=formHarness(key);h.ctx.findOrCreateLedgerCustomer('Nasir Bagali','COMPANY-MOBILE','COMPANY-VAT','Company address','COMPANY-NATIONAL');assert.equal(h.data.customers[0].vat,'NASIR-VAT');assert.equal(h.data.customers[0].mobile,'');assert.equal(h.writes,0);});
test('New invoice customers receive their own explicit profile and a distinct ID',()=>{const h=formHarness('INV');const c=h.ctx.findOrCreateLedgerCustomer('Third customer','03','THIRD-VAT','Third address','THIRD-NATIONAL');assert.equal(c.profile_v226.vat,'THIRD-VAT');assert.equal(h.data.customers.length,3);assert.notEqual(c.id,h.data.customers[0].id);});
test('The actual cloud ledger merger separates profiles and entries if two devices reused an ID',()=>{
  const start=html.indexOf('  function nagCloudText('),end=html.indexOf('  function nagMergeCloudValue(',start),storage=new Map();const ctx={window:{NagCustomerProfiles:P,NagInvoiceLinks:A},localStorage:{getItem:k=>storage.get(k)||null,setItem:(k,v)=>storage.set(k,v)}};vm.createContext(ctx);vm.runInContext(html.slice(start,end),ctx);
  const c=customers(),local={customers:[c[0]],entries:{nasir:[{id:'n',invoiceNo:'INV-1',bill:5}]},settings:{}},cloud={customers:[{...c[1],id:'nasir'}],entries:{nasir:[{id:'c',invoiceNo:'INV-2',bill:7}]},settings:{}};
  const merged=ctx.nagCloudMergeLedger(local,cloud),nasir=merged.customers.find(x=>x.name===c[0].name),company=merged.customers.find(x=>x.name===c[1].name);assert.notEqual(nasir.id,company.id);assert.equal(nasir.address,'Nasir address');assert.equal(company.address,'Company address');assert.equal(merged.entries[nasir.id][0].bill,5);assert.equal(merged.entries[company.id][0].bill,7);
});
test('Repeated real history recovery cannot refill a cleared customer VAT or address',()=>{
  const a=html.indexOf('  function nagApplyLedgerRecoveryV256('),b=html.indexOf('\n  function nagApplyCustomerLedgerEditDeleteV224',a),shell={};vm.createContext(shell);vm.runInContext(html.slice(a,b),shell);
  const nasir={...customers()[0],vat:'',address:'',mobile:'',nationalAddress:''};P.stamp(nasir);const d={customers:[nasir],entries:{nasir:[]},settings:{}},values=new Map([['nag_ledger_v1',JSON.stringify(d)],['nag_invoice_history_v1',JSON.stringify([{no:'INV-10',c_name:'Nasir Bagali',c_vat:'COMPANY-VAT',c_addr:'Company address',c_mobile:'COMPANY-MOBILE',grand:5,date:'2026-11-01'}])]]),calls=[];
  const ctx={window:{parent:{NagInvoiceLinks:A,NagCustomerProfiles:P}},localStorage:{getItem:k=>values.get(k)||null,setItem:(k,v)=>values.set(k,v)},document:{addEventListener:(event,fn)=>calls.push(fn)},setTimeout:fn=>calls.push(fn),setInterval:fn=>calls.push(fn)};vm.createContext(ctx);const doc=shell.nagApplyLedgerRecoveryV256('<body></body>','Customer Ledger');vm.runInContext(doc.match(/<script id='NAG_LEDGER_RECOVERY_V256'>([\s\S]*?)<\/script>/)[1],ctx);for(let i=0;i<3;i++)calls.forEach(fn=>fn());const c=JSON.parse(values.get('nag_ledger_v1')).customers[0];assert.equal(c.vat,'');assert.equal(c.address,'');assert.equal(c.mobile,'');
});
console.log(count+' customer profile tests passed.');
